import {CardSearch} from './card-search.mjs';
import {indexCards,newDeck,validateDeck,addCard,importText,deckText,deckStats,DeckStore,zones,zoneLabels} from './deck-model.mjs?v=2';
import {mountPresentation,descriptionHTML,rarityLabel,escapeHTML as esc} from './deck-presentation.mjs';
import {setProxyDeck} from './proxy-printer.mjs?v=3';
const download=(name,data,type)=>{const u=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),60000);};
let index,store=new DeckStore(),trash=false,undo=[],lastId,search='',zone='auto',filters={};
export async function mountDeckBuilder(root,cards,lang,id){
 const t=(de,en)=>lang==='en'?en:de,zname=z=>zoneLabels[z][lang==='en'?1:0],route=(id,edit=false)=>`#/${lang}/decks${id?'/'+id:''}${edit?'?mode=edit':''}`, $=s=>root.querySelector(s);
 let editing=new URLSearchParams(location.hash.split('?')[1]||'').get('mode')==='edit';
 if(lastId!==id){undo=[];search='';filters={};lastId=id;}
 root.innerHTML=`<p>${t('Decks werden geladen …','Loading decks …')}</p>`;
 try{if(!index){const response=await fetch('data/card-identities.json');if(!response.ok)throw Error('Card identities unavailable');index=indexCards(cards,await response.json());}if(!location.hash.includes('/decks'))return;render();}catch(e){root.innerHTML=`<h1>${t('Decks nicht verfügbar','Decks unavailable')}</h1><p>${esc(e.message)}</p>`;}
 function message(s){$('#deck-message').textContent=s;}
 function current(){return store.read().find(d=>d.id===id);}
 function save(d,remember=true){try{if(d.coverPrintingId&&!d.entries.some(e=>e.printingId===d.coverPrintingId))d.coverPrintingId='';validateDeck(d,index);if(remember){undo.push(structuredClone(current()));if(undo.length>40)undo.shift();}store.save(d,index);render();message(t('In diesem Browser gespeichert.','Saved in this browser.'));return true;}catch(e){message(t('Speichern fehlgeschlagen: ','Save failed: ')+e.message);return false;}}
 function button(label,action){return `<button class="pill" data-action="${action}">${label}</button>`;}
 function render(){
  const deck=current();root.innerHTML=`<div class="deck-heading"><h1>${deck?esc(deck.name):t('Meine Decks','My decks')}</h1><a class="pill" href="#/${lang}/account">${t('Konto & Online-Decks','Account & online decks')}</a></div><p id="deck-message" role="status" aria-live="polite"></p>`;
  if(id&&!deck){root.innerHTML+=`<p>${t('Deck nicht gefunden.','Deck not found.')}</p><a href="${route('')}">${t('Meine Decks','My decks')}</a>`;return;}
  if(!deck){renderList();return;}
  if(deck.trashed){root.innerHTML+=`<p>${t('Dieses Deck liegt im Papierkorb.','This deck is in the trash.')}</p>${button(t('Wiederherstellen','Restore'),'restore')}`;bind({restore:()=>save({...deck,trashed:false})});return;}
  root.innerHTML+=`<div class="deck-toolbar"><a class="pill" href="${route('')}">← ${t('Meine Decks','My decks')}</a>${button(editing?t('Präsentation','Presentation'):t('Bearbeiten','Edit'),'mode')}${button(t('Beschreibung & Titelbild','Description & cover'),'description')}${editing?button(t('Rückgängig','Undo'),'undo'):''}<details class="deck-actions"><summary>${t('Weitere Aktionen','More actions')}</summary><div>${button(t('Kopie erstellen','Make a copy'),'copy')}${button(t('Text exportieren','Export text'),'text')}${button('JSON','json')}${button('Proxies','proxy')}${button(t('Online speichern','Save online'),'cloud')}${button(t('Teilen','Share'),'share')}${button(t('In Papierkorb verschieben','Move to trash'),'trash')}</div></details></div>`;
  if(editing)editor(deck);else {root.innerHTML+='<div id="deck-presentation"></div>';mountPresentation($('#deck-presentation'),deck,index,lang);}
  bind({mode:()=>{editing=!editing;history.replaceState(null,'',route(id,editing));render();},description:()=>descriptionEditor(deck),undo:()=>{const previous=undo.pop();if(previous?.id===id)save(previous,false);else message(t('Keine Änderung zum Rückgängigmachen.','Nothing to undo.'));},copy:()=>copy(deck),text:()=>download('blutbank-deck.txt',deckText(deck,index),'text/plain'),json:()=>download('blutbank-deck.json',JSON.stringify(deck,null,2),'application/json'),proxy:()=>{setProxyDeck(deck.entries.filter(e=>e.zone!=='maybe').map(e=>({id:e.printingId,quantity:e.quantity})),cards);location.hash=`#/${lang}/proxy`;},trash:()=>{if(save({...deck,trashed:true}))location.hash=route('');},import:()=>{const parsed=importText($('#deck-import').value,index);if(parsed.errors.length){message(t('Nicht importiert. Unbekannte/ungültige Zeilen: ','Not imported. Unknown/invalid lines: ')+parsed.errors.map(e=>`${e.line}: ${e.name}`).join('; '));return;}save(merge({...deck,entries:[...deck.entries,...parsed.entries]}));},cloud:()=>online(deck,false),share:()=>online(deck,true)});
 }
 async function online(deck,share){try{const api=await import('./deck-online.mjs?v=2');if(share){const token=await api.shareOnline(deck);message(t('Freigabelink: ','Sharing link: '));const a=document.createElement('a');a.href=`#/${lang}/shared/${token}`;a.textContent=a.href;$('#deck-message').append(a);}else {await api.saveOnline(deck);message(t('Online gespeichert.','Saved online.'));}}catch(e){message(e.message);}}
 function editor(deck){
  const stats=deckStats(deck,index);
  root.innerHTML+=`<p class="muted">${t('Änderungen werden automatisch in diesem Browser gespeichert. Für andere Geräte „Online speichern“ verwenden.','Changes are saved automatically in this browser. Use “Save online” for other devices.')}</p><div class="deck-edit-workspace"><section class="deck-search"><h2>${t('Karten suchen','Find cards')}</h2><input type="search" id="deck-search" aria-label="${t('Karten durchsuchen','Search cards')}" value="${esc(search)}"><div class="deck-search-filters">${filterSelect('color',t('Farbe','Color'),[...new Set(cards.flatMap(c=>c.text?.colors||[]))].sort())}${filterSelect('type',t('Typ','Type'),[...new Set(cards.flatMap(c=>c.text?.types||[]))].sort())}${filterSelect('rarity',t('Seltenheit','Rarity'),['K','N','L','F'])}<label>${t('ASP maximal','Maximum ASP')}<input type="number" min="0" max="99" data-search-filter="aspMax" value="${esc(filters.aspMax||'')}"></label></div><details><summary>${t('Weitere Suchoptionen','More search options')}</summary><div class="deck-search-filters"><label>${t('Kartentext','Rules text')}<input type="search" data-search-filter="text" value="${esc(filters.text||'')}"></label>${filterSelect('set',t('Edition','Set'),[...new Set(cards.map(c=>c.set))])}</div><p class="muted">${t('In der Suche sind Kombinationen wie Flying asp<=3 oder "draw a card" möglich.','Search supports combinations such as Flying asp<=3 or "draw a card".')}</p></details><label>${t('Hinzufügen zu','Add to')}<select id="deck-zone"><option value="auto">${t('Automatisch (Herrscher / Rune / Spell)','Automatic (Sovereign / Rune / Spell)')}</option>${zones.map(z=>`<option value="${z}" ${zone===z?'selected':''}>${zname(z)}</option>`).join('')}</select></label><div id="deck-results"></div></section><section class="deck-cards"><h2>${t('Deckliste','Deck list')} <small>${stats.total}</small></h2><div class="deck-live-check" role="status">${stats.issues.length?`<ul>${stats.issues.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:t('Keine Überschreitung bekannter Kopienlimits.','No known copy limits exceeded.')} <a href="#/${lang}/rules/2.4">${t('Regeln','Rules')}</a></div>${zones.map(z=>renderZone(deck,z)).join('')}<details class="deck-import"><summary>${t('Kartenliste importieren','Import card list')}</summary><p>${t('Eine Karte pro Zeile, z. B. 3x Oracle. Wird zum Deck hinzugefügt. Pool-Zuordnung anschließend prüfen.','One card per line, e.g. 3x Oracle. Adds to the deck. Check pool assignments afterwards.')}</p><textarea id="deck-import" rows="5" aria-label="${t('Kartenliste importieren','Import card list')}"></textarea>${button(t('Liste hinzufügen','Add list'),'import')}</details></section></div>`;
  $('#deck-zone').onchange=e=>zone=e.target.value;$('#deck-search').oninput=e=>{search=e.target.value;results();};
  root.querySelectorAll('[data-search-filter]').forEach(el=>el.oninput=()=>{filters[el.dataset.searchFilter]=el.value;results();});results();
  root.querySelectorAll('[data-quantity]').forEach(el=>el.onchange=el.onblur=()=>{const i=Number(el.dataset.quantity),n=Number(el.value);if(current().entries[i]?.quantity!==n)quantity(i,n);});
  root.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{const i=Number(el.dataset.entry);quantity(i,deck.entries[i].quantity+Number(el.dataset.step));});
  root.querySelectorAll('[data-version]').forEach(el=>el.onchange=()=>{const d=structuredClone(deck);d.entries[Number(el.dataset.version)].printingId=el.value;save(merge(d));});
  root.querySelectorAll('[data-zone]').forEach(el=>el.onchange=()=>{const d=structuredClone(deck);d.entries[Number(el.dataset.zone)].zone=el.value;save(merge(d));});
  root.querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>quantity(Number(el.dataset.remove),0));
  function quantity(i,n){const d=structuredClone(deck);if(n===0)d.entries.splice(i,1);else d.entries[i].quantity=n;save(d);}
 }
 function filterSelect(key,label,values){return `<label>${label}<select data-search-filter="${key}"><option value="">${t('Alle','All')}</option>${values.map(v=>`<option value="${esc(v)}" ${filters[key]===v?'selected':''}>${esc(CardSearch.label(v,lang))}</option>`).join('')}</select></label>`;}
 function merge(d){const map=new Map();for(const e of d.entries){const k=e.printingId+':'+e.zone;if(map.has(k))map.get(k).quantity+=e.quantity;else map.set(k,{...e});}return {...d,entries:[...map.values()]};}
 function renderZone(deck,z){
  const entries=deck.entries.map((e,i)=>({...e,i})).filter(e=>e.zone===z);
  return `<section class="deck-section"><h3>${zname(z)} <span>${entries.reduce((n,e)=>n+e.quantity,0)}</span></h3>${entries.map(e=>{const g=index.find(g=>g.id===e.cardId),c=g.variants.find(c=>c.id===e.printingId),count=deck.entries.filter(x=>x.cardId===g.id&&x.zone!=='maybe').reduce((n,x)=>n+x.quantity,0),limit={K:4,N:3,L:2,F:1}[c.text?.rarity];return `<article class="deck-entry ${limit&&count>limit&&z!=='maybe'?'over-limit':''}"><div class="deck-entry-main"><div class="quantity-control"><button data-entry="${e.i}" data-step="-1" aria-label="${esc(g.name)} −">−</button><input type="number" min="0" max="300" value="${e.quantity}" data-quantity="${e.i}" aria-label="${esc(g.name)} ${t('Anzahl','quantity')}"><button data-entry="${e.i}" data-step="1" aria-label="${esc(g.name)} +">+</button></div><a class="deck-card-name" href="#/${lang}/card/${c.id}">${esc(g.name)}<img class="deck-hover" src="${esc(c.image)}" alt="" loading="lazy"></a><button class="pill" data-remove="${e.i}" aria-label="${t('Entfernen','Remove')} ${esc(g.name)}">×</button></div><small class="deck-rarity">${esc(rarityLabel(c,lang))} · ${count}${limit?' / '+limit:''} ${t('im Deck','in deck')}</small><details class="deck-printing"><summary>${esc(c.set)} · ${esc(c.code||'')} · ${t('Version & Bereich','Printing & zone')}</summary><div class="deck-entry-options"><select data-zone="${e.i}" aria-label="${esc(g.name)} ${t('Bereich','zone')}">${zones.map(z=>`<option value="${z}" ${z===e.zone?'selected':''}>${zname(z)}</option>`).join('')}</select><select data-version="${e.i}" aria-label="${esc(g.name)} ${t('Version','printing')}">${g.variants.map((v,i)=>`<option value="${v.id}" ${v.id===c.id?'selected':''}>${esc(v.set)} · ${esc(v.code||'')} · ${esc(v.variant||i+1)}</option>`).join('')}</select></div></details></article>`;}).join('')||`<p class="muted">${t('Noch keine Karten','No cards yet')}</p>`}</section>`;
 }
 function results(){
  const activeFilters=Object.fromEntries(Object.entries(filters).filter(([,v])=>v!=='')),groups=index.map(g=>({...g,match:g.variants.find(c=>CardSearch.matches(c,{q:search,...activeFilters}))})).filter(g=>g.match),deck=current();
  $('#deck-results').innerHTML=`<p class="muted">${groups.length} ${t('Treffer','results')}${groups.length>60?' · '+t('erste 60; Suche eingrenzen','first 60; refine search'):''}</p>${groups.slice(0,60).map(g=>{const n=deck.entries.filter(e=>e.cardId===g.id).reduce((n,e)=>n+e.quantity,0);return `<div class="deck-search-result"><button class="deck-card-name preview-name" data-preview="${g.match.id}">${esc(g.name)}<img class="deck-hover" src="${esc(g.match.image)}" alt="${esc(g.name)}" loading="lazy"></button>${n?`<small>${n}×</small>`:''}<button class="pill" data-add="${g.id}" data-printing="${g.match.id}" aria-label="${esc(g.name)} ${t('hinzufügen','add')}">+</button></div>`;}).join('')}`;
  root.querySelectorAll('[data-preview]').forEach(b=>b.onclick=()=>b.classList.toggle('show-preview'));
  root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const g=index.find(g=>g.id===b.dataset.add),c=g.variants.find(c=>c.id===b.dataset.printing),types=c.text?.types||[],target=zone==='auto'?(types.includes('Sovereign')?'sovereign':types.includes('Rune')?'rune':'spell'):zone;const scroll=window.scrollY;if(save(addCard(current(),g,c.id,target))){window.scrollTo(0,scroll);const next=root.querySelector(`[data-add="${g.id}"]`);next?.focus({preventScroll:true});}});
 }
 function descriptionEditor(deck){
  const dialog=document.createElement('dialog');dialog.className='deck-description-dialog';dialog.setAttribute('aria-label',t('Beschreibung & Titelbild','Description & cover'));const available=[...new Set(deck.entries.map(e=>e.printingId))].map(id=>cards.find(c=>c.id===id));
  dialog.innerHTML=`<form><h2>${t('Beschreibung & Titelbild','Description & cover')}</h2><label>${t('Deckname','Deck name')}<input name="name" maxlength="120" required value="${esc(deck.name)}"></label><label>${t('Kurzbeschreibung','Short description')}<textarea name="summary" maxlength="300" rows="2">${esc(deck.summary||'')}</textarea></label><label>${t('Titelkarte','Cover card')}<select name="cover"><option value="">${t('Kein Titelbild','No cover')}</option>${available.map(c=>`<option value="${c.id}" ${deck.coverPrintingId===c.id?'selected':''}>${esc(c.name)} · ${esc(c.set)}</option>`).join('')}</select></label><label>${t('Ausführliche Beschreibung','Full description')}<textarea name="description" maxlength="5000" rows="10">${esc(deck.description)}</textarea></label><p class="muted">${t('Überschriften mit #, Listen mit - am Zeilenanfang.','Use # for headings and - at the start of a line for lists.')}</p><details><summary>${t('Vorschau','Preview')}</summary><div id="description-preview"></div></details><p class="description-error" role="status"></p><div class="deck-toolbar"><button type="submit" class="pill">${t('Speichern','Save')}</button><button type="button" class="pill" id="cancel-description">${t('Abbrechen','Cancel')}</button></div></form>`;
  root.append(dialog);const form=dialog.querySelector('form'),preview=()=>dialog.querySelector('#description-preview').innerHTML=descriptionHTML(form.elements.description.value);form.elements.description.oninput=preview;preview();
  dialog.querySelector('#cancel-description').onclick=()=>dialog.close();dialog.onclose=()=>{dialog.remove();root.querySelector('[data-action="description"]')?.focus();};
  form.onsubmit=e=>{e.preventDefault();const name=form.elements.name.value.trim();if(!name){dialog.querySelector('.description-error').textContent=t('Bitte einen Namen eingeben.','Please enter a name.');return;}const d={...structuredClone(deck),name,summary:form.elements.summary.value,description:form.elements.description.value,coverPrintingId:form.elements.cover.value};if(save(d))dialog.close();else dialog.querySelector('.description-error').textContent=t('Speichern fehlgeschlagen.','Save failed.');};dialog.showModal();
 }
 function bind(actions){root.querySelectorAll('[data-action]').forEach(b=>b.onclick=actions[b.dataset.action]);}
 function copy(d){const clone={...structuredClone(d),id:crypto.randomUUID(),name:(t('Kopie von ','Copy of ')+d.name).slice(0,120),trashed:false};delete clone.remoteRevision;try{store.save(clone,index);undo=[];location.hash=route(clone.id);}catch(e){message(e.message);}}
 function renderList(){root.innerHTML+=`<div class="deck-toolbar">${button(t('Neues Deck','New deck'),'new')}${button(trash?t('Meine Decks','My decks'):t('Papierkorb','Trash'),'toggle')}<label class="pill">${t('JSON importieren','Import JSON')}<input id="deck-file" type="file" accept="application/json,.json"></label></div><div class="deck-list">${store.read().filter(d=>!!d.trashed===trash).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)).map(d=>{const cover=cards.find(c=>c.id===d.coverPrintingId);return `<article>${cover?`<img class="deck-list-cover" src="${esc(cover.image)}" alt="" loading="lazy">`:''}<div><a href="${route(d.id)}"><strong>${esc(d.name)}</strong></a><small>${deckStats(d,index).total} ${t('Karten','cards')} · ${new Date(d.updatedAt).toLocaleDateString(lang)}</small>${d.summary?`<p>${esc(d.summary)}</p>`:''}</div><a class="pill" href="${route(d.id)}">${t('Ansehen','View')}</a>${!trash?`<a class="pill" href="${route(d.id,true)}">${t('Bearbeiten','Edit')}</a>`:''}</article>`;}).join('')||`<p class="empty">${t('Hier sind noch keine Decks.','No decks here yet.')}</p>`}</div>`;
 bind({new:()=>{const d=newDeck(t('Neues Deck','New deck'));try{store.save(d,index);undo=[];location.hash=route(d.id,true);}catch(e){message(e.message);}},toggle:()=>{trash=!trash;render();}});
 $('#deck-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>300000)throw Error(t('Datei zu groß.','File too large.'));copy(validateDeck(JSON.parse(await f.text()),index));}catch(error){message(error.message);}};
 }
}
